/**
 * Pattern quiz question bank. Each question is a short scenario; the learner picks the pattern
 * (or technique) that fits. `pattern` is a slug from ALL_PATTERNS in patterns.ts.
 *
 * Questions are written as tuples via `q()` (correct option first) and spread so the correct
 * answer lands in a varying position (see `place`). Owned by the patterns/quiz agent.
 */

export type QuizDifficulty = 'Easy' | 'Medium' | 'Hard';

export interface QuizQuestion {
  id: string;
  /** Pattern slug this question tests. */
  pattern: string;
  difficulty: QuizDifficulty;
  question: string;
  options: [string, string, string, string];
  /** Index (0-3) of the correct option. */
  answer: 0 | 1 | 2 | 3;
  hint: string;
  /** Names the pattern and says why the other options fail. */
  explanation: string;
}

type Raw = [pattern: string, difficulty: QuizDifficulty, question: string, right: string, w1: string, w2: string, w3: string, hint: string, explanation: string];

