/** Put the correct option at a varying position so answers are not predictable. */
function place(raw: Raw, index: number): QuizQuestion {
  const [pattern, difficulty, question, right, w1, w2, w3, hint, explanation] = raw;
  const answer = ((index * 3 + 2) % 4) as 0 | 1 | 2 | 3;
  const wrong = [w1, w2, w3];
  const options = [] as unknown as [string, string, string, string];
  let w = 0;
  for (let i = 0; i < 4; i++) options[i] = i === answer ? right : wrong[w++];
  return { id: `q${String(index + 1).padStart(2, '0')}`, pattern, difficulty, question, options, answer, hint, explanation };
}

export const QUIZ_QUESTIONS: QuizQuestion[] = RAW.map(place);

export const QUIZ_LENGTH = 10;
